    tabTitle: ['', [Validators.required]]
  });

  constructor(private formBuilder: FormBuilder) {}

  ngOnInit(): void {}

  switchTab(index: number): void {
    if (index >= 0 && index < this.tabs.length) {
      this.selectedTabIndex = index;
    }
  }

  addNewTab(): void {
    const newTab = this.tabs[this.tabs.length - 1];
    const newFormGroup = this.formBuilder.group({
      tabTitle: [newTab, [Validators.required]]
    });
    this.tabs.push(newTab);
    this.tabs.forEach((tab, i) => {
      if (i === this.tabs.indexOf(newTab)) {
        this.formGroup.addControl(tab, newFormGroup);
      } else {
        this.formGroup.removeControl(tab);
      }
    });
  }

