    private permissionsService: PermissionsService,
  ) {}

  @Get()
  async getPermissions(@Request() req) {
    const user = await this.userService.getUserByToken(req.headers['authorization']);
    if (!user) return null;

    const permissions = await this.permissionsService.getPermissions(user.role);
